var t=`0072-hortobagyi-palacsinta`;var n=`world-0072`;var o=`HU`;var r=`eastern-europe`;var a=4;var s=53;var l={en:`Hortobágyi Palacsinta`,ua:`Гортобадьські млинці`};var h={en:`A classic dish from Hungary, featuring chicken egg, whole cow milk, ground chicken, yellow onion. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Угорщина. Основні складники: куряче яйце, цільне коров'яче молоко, курячий фарш, жовта цибуля. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:8,i:[[`all-purpose-flour`,240,`g`],[`chicken-egg`,3,`pcs`],[`whole-cow-milk`,500,`ml`],[`table-salt`,3,`g`]]},{en:`Swirl thin layers of batter in a lightly greased hot pan. Cook both sides, about 18 minutes per batch, to make flexible crepes.`,ua:`Наливайте тонкий шар тіста на злегка змащену розігріту сковороду. Обсмажуйте з обох боків, приблизно 18 хвилин на партію, щоб отримати еластичні млинці.`,t:[`pan-frying`],m:18,i:[[`sunflower-oil`,35,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-chicken`,380,`g`],[`yellow-onion`,110,`g`],[`sweet-paprika`,9,`g`],[`garlic`,2,`clove`]]},{en:`Spread the prepared filling over the crepes, roll or fold them, and warm through if the filling requires it.`,ua:`Розподіліть готову начинку по млинцях, згорніть рулетиками або конвертами й за потреби прогрійте.`,t:[`rolling-stuffed-food`],m:10,i:[]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:5,i:[[`sour-cream`,230,`g`],[`heavy-cream`,140,`ml`]]}];var c={slug:t,id:n,country:`HU`,region:r,servings:4,minutes:53,title:l,text:h,steps:g};export{o as country,c as default,n as id,s as minutes,r as region,a as servings,t as slug,g as steps,h as text,l as title};